                    <h2 id="admin-vendors-management-POSTapi-v1-admin-vendors">Create Vendor</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>Create a new vendor in the system.</p>

<span id="example-requests-POSTapi-v1-admin-vendors">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/admin/vendors" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"owner_id\": \"architecto\",
    \"name\": {
        \"en\": \"b\",
        \"ar\": \"n\"
    },
    \"email\": \"ashly64@example.com\",
    \"phone\": \"vdljnikhwaykcmyu\",
    \"formatted_address\": \"w\",
    \"type\": \"pharmacy\",
    \"latitude\": -89,
    \"longitude\": -180,
    \"is_active\": true,
    \"status\": \"busy\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/admin/vendors"
);

const headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "owner_id": "architecto",
    "name": {
        "en": "b",
        "ar": "n"
    },
    "email": "ashly64@example.com",
    "phone": "vdljnikhwaykcmyu",
    "formatted_address": "w",
    "type": "pharmacy",
    "latitude": -89,
    "longitude": -180,
    "is_active": true,
    "status": "busy"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

